css:
:root {
  --speed-background: #F7F9FB;
  --speed-border: #CBD5E1;
  --speed-label-color: #527DA5;
  --speed-value-color: #263D52;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  background: transparent !important;
}

.speed-widget,
.speed-widget * {
  box-sizing: border-box;
}

.speed-widget {
  width: 100%;
  height: 100%;
  padding: 3px 5px;
  overflow: hidden;

  font-family: "Segoe UI", Arial, sans-serif;
  background: transparent;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.speed-frame {
  display: flex;
  align-items: center;
  gap: 12px;

  width: 100%;
  height: 100%;
  padding: 0 15px;
  overflow: hidden;

  border: 1px solid var(--speed-border);
  border-radius: 6px;
  background: var(--speed-background);
}

.speed-label {
  flex: 0 1 auto;
  min-width: 0;
  max-width: 55%;

  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;

  color: var(--speed-label-color);
  font-size: 14px;
  font-weight: 400;
  line-height: 1.2;
}

.speed-value-area {
  display: flex;
  flex: 1 1 0;
  align-items: center;
  justify-content: flex-end;

  min-width: 0;
  height: 100%;
  overflow: hidden;
}

.speed-reading {
  display: flex;
  flex: 0 0 auto;
  align-items: baseline;
  gap: 0.25em;

  font-size: 24px;
  font-weight: 400;
  line-height: 1;
  white-space: nowrap;
}

.speed-value {
  display: block;
  flex: 0 0 auto;

  color: var(--speed-value-color);
  font-variant-numeric: tabular-nums;
}

.speed-unit {
  display: block;
  flex: 0 0 auto;

  color: var(--speed-label-color);
  font-size: 0.6em;
}

