"use strict";

(function () {
  let valueArea = null;
  let readingElement = null;
  let valueElement = null;
  let lastUpdate = null;
  let resizeObserver = null;

  /*
   * Ajusta el valor y la unidad al espacio disponible
   * a la derecha del título.
   */
  function fitValue() {
    if (!valueArea || !readingElement) return;

    const availableWidth = valueArea.clientWidth;
    const availableHeight = valueArea.clientHeight;

    if (availableWidth <= 0 || availableHeight <= 0) return;

    const baseSize = Math.min(30, availableHeight * 0.75);

    readingElement.style.fontSize = baseSize + "px";

    const textWidth =
      readingElement.getBoundingClientRect().width;

    if (textWidth > availableWidth) {
      readingElement.style.fontSize =
        (baseSize * availableWidth / textWidth) + "px";
    }
  }

  function render(w) {
    if (!valueElement || !readingElement) return;

    const raw = w ? w.value : null;
    let numericValue = NaN;

    if (typeof raw === "number") {
      numericValue = raw;
    } else if (
      typeof raw === "string" &&
      raw.trim() !== ""
    ) {
      numericValue = Number(raw);
    }

    const valid = Number.isFinite(numericValue);
    const text = valid ? String(numericValue) : "—";

    /*
     * La variable debe estar expresada en m/min.
     * Se muestra directamente, sin conversión ni
     * redondeo adicional.
     */
    valueElement.textContent = text;

    readingElement.setAttribute(
      "aria-label",
      valid
        ? "Velocidad de línea: " + text + " metros por minuto"
        : "Velocidad de línea: sin valor numérico"
    );

    fitValue();
  }

  /* Recibe las actualizaciones de la variable del PLC */
  window.onWidgetUpdate = function (w) {
    lastUpdate = w;
    render(w);
  };

  function initialize() {
    valueArea = document.querySelector(".speed-value-area");
    readingElement = document.querySelector(".speed-reading");
    valueElement = document.querySelector(".speed-value");

    if (!valueArea || !readingElement || !valueElement) return;

    render(lastUpdate || window.WIDGET || null);

    if (typeof ResizeObserver !== "undefined") {
      resizeObserver = new ResizeObserver(fitValue);
      resizeObserver.observe(valueArea);
    } else {
      window.addEventListener("resize", fitValue);
    }

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(fitValue);
    }
  }

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      initialize,
      { once: true }
    );
  } else {
    initialize();
  }
})();
